    edge=[v for v,n in counts.items() if v!=bg]
    bar=max(edge,key=lambda v:counts[v])
    markers=[(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg,bar)]
    # A marker's color is used to fill the strip from each marker toward a bar;
    # marker itself is changed to 4, and the bar color supplies the row/column span.
    for r,c in markers:
        out[r][c]=4
        if c < w//2:
            for cc in range(c+1,w):
                if grid[r][cc]==bg: out[r][cc]=grid[r][c]
        else:
