def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    # Find the two horizontal edge bars and map their columns by the offset of their starts.
    top = [c for c, v in enumerate(grid[0]) if v != bg]
    bottom = [c for c, v in enumerate(grid[-1]) if v != bg]
    if not top or not bottom:
        return out
    shift = min(top) - min(bottom)
    # A dot's column identifies the corresponding column in the opposite bar.
    for r in range(1, h - 1):
        for c in range(w):
            if grid[r][c] == bg or c in top or c in bottom:
                continue
            color = grid[r][c]
            out[r][c] = 4
            mapped = c + shift if c in bottom else c - shift
            # Draw from both edge bars up/down to the marker row in the matched columns.
            if c in bottom and min(bottom) <= c <= max(bottom) and min(top) <= mapped <= max(top):
                for rr in range(r + 1, h - 1):
                    out[rr][c] = color
                for rr in range(1, h):
                    out[rr][mapped] = color
            elif c in top and min(top) <= c <= max(top) and min(bottom) <= mapped <= max(bottom):
                for rr in range(1, r):
                    out[rr][c] = color
                for rr in range(1, h):
                    out[rr][mapped] = color
    return out
